# -*- coding: utf-8 -*-
"""اصلاح چت خصوصی کلاس مجازی؛ فایل‌های قبلی را ابتدا پشتیبان می‌گیرد."""
from pathlib import Path
from datetime import datetime
import ast, base64, gzip, json, shutil, sys

PAYLOAD = r""""""

def find_project():
    candidates = [Path.cwd(), Path(__file__).resolve().parent]
    for base in list(candidates):
        candidates.extend(list(base.parents))
    for base in candidates:
        if (base / 'manage.py').is_file() and (base / 'classroom' / 'consumers.py').is_file():
            return base
    while True:
        raw = input('مسیر پوشه پروژه (محل manage.py) را وارد کن: ').strip().strip('"')
        p = Path(raw).expanduser()
        if (p / 'manage.py').is_file() and (p / 'classroom' / 'consumers.py').is_file():
            return p.resolve()
        print('این مسیر پروژه Django معتبر نیست؛ فایل manage.py و classroom/consumers.py باید وجود داشته باشند.')

def main():
    print('=' * 68)
    print('اصلاح چت خصوصی کلاس مجازی')
    print('دانش‌آموز فقط برای استاد پیام می‌فرستد؛ استاد صندوق پیام‌های جداگانه دارد.')
    print('=' * 68)
    root = find_project()
    data = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    decoded = {k: base64.b64decode(v) for k, v in data.items()}
    backup = root / ('backup_private_chat_' + datetime.now().strftime('%Y%m%d_%H%M%S'))
    for rel in decoded:
        target = root / rel
        if not target.is_file():
            raise SystemExit(f'فایل موردنیاز پیدا نشد: {target}')
    print(f'پروژه: {root}')
    print('این فایل‌ها اصلاح می‌شوند:')
    for rel in decoded: print(' -', rel)
    if input('ادامه بدهم؟ [Y/n]: ').strip().lower() in ('n','no'):
        print('لغو شد؛ هیچ فایلی تغییر نکرد.')
        return
    for rel, content in decoded.items():
        target = root / rel
        saved = backup / rel
        saved.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, saved)
        target.write_bytes(content)
    try:
        ast.parse((root / 'classroom' / 'consumers.py').read_text(encoding='utf-8'))
    except Exception:
        for rel in decoded:
            shutil.copy2(backup / rel, root / rel)
        raise
    print('اصلاحات با موفقیت اعمال شدند.')
    print('پشتیبان فایل‌های قبلی:', backup)
    print('اکنون اجرا کن:')
    print('  .venv/Scripts/python.exe manage.py check')
    print('  .venv/Scripts/python.exe manage.py runserver')
    print('نکته: برای دیدن صندوق پیام استاد، استاد و دانش‌آموز هر دو باید وارد همان کلاس شوند.')

if __name__ == '__main__':
    try: main()
    except Exception as exc:
        print('خطا:', exc)
        sys.exit(1)
